Definition wpiece_ok (iv : Z * Z) : Prop := AIMG_HI <= fst iv \/ (0x18c1c8 <= fst iv /\ snd iv <= 0x5dc210).

Lemma disjoint_img2 : forall W A n, Forall wpiece_ok W -> 0 <= n ->
